def count_combinations(n, s, k, memo=None):
    if memo is None:
        memo = {}
    if (n, s, k) in memo:
        return memo[(n, s, k)]
    if n == 1:
        return 1 if 1 <= k <= s else 0
    if k < n or k > n * s:
        return 0
    result = 0
    for i in range(1, s + 1):
        result += count_combinations(n - 1, s, k - i, memo)
    memo[(n, s, k)] = result
    return result

def outcome(n, s, k):
    return count_combinations(n, s, k)
