    """Find common factors of two numbers."""
    factors = []
    for i in range(2, min(num1, num2) + 1):
        if num1 % i == 0 and num2 % i == 0:
            factors.append(i)
    return factors

def smallest_common_factor(lst):
    """Find the smallest common factor of all numbers in the list."""
    if not lst:
        return 1

    # Start with common factors of the first two numbers
    common_factors = find_common_factors(lst[0], lst[1])

    # Intersect with common factors of the next number
    for num in lst[2:]:
        common_factors = [factor for factor in common_factors if num % factor == 0]

    # If no common factors found, return 1
    if not common_factors:
        return 1

    return min(common_factors)

def scf(lst):
    """Entrypoint function to find the smallest common factor of all integers in the array."""
    return smallest_common_factor(lst)
