def missing_alphabets(s):
    def get_missing_letters(s):
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
        missing = []
        for char in alphabet:
            count = s.count(char)
            if count == 0:
                missing.append(char)
            elif count > 1:
                missing.extend([char] * (count - 1))
        return ''.join(missing)

    def find_repeated_missing_letters(missing):
        repeated = []
        for i in range(len(missing)):
            if i == 0 or missing[i] != missing[i - 1]:
                repeated.append(missing[i])
            else:
                repeated[-1] += missing[i]
        return ''.join(repeated)

    missing = get_missing_letters(s)
    repeated_missing = find_repeated_missing_letters(missing)
    return repeated_missing

